<script setup>
import { onMounted, ref } from 'vue';
import { apiFetch, listFrom } from '../../app/services/api';
const vendors = ref([]); const search = ref(''); const category = ref('All');
async function load() { const params = new URLSearchParams({ ...(category.value !== 'All' ? { category: category.value } : {}), ...(search.value ? { search: search.value } : {}) }); try { vendors.value = listFrom(await apiFetch(`/vendors?${params}`), ['vendors']); } catch { vendors.value = []; } }
onMounted(load);
</script>
<template><section class="content page-content"><div class="page-header"><div><p class="eyebrow">Local makers</p><h1>Vendors</h1></div><input v-model="search" class="search-input" placeholder="Search vendors" @input="load" /></div><div class="filter-bar"><button v-for="item in ['All','Bakery','Crafts','Skincare','Clothing','Home & Decor','Food Truck']" :key="item" class="chip" :class="{ active: category === item }" type="button" @click="category = item; load()">{{ item }}</button><span>{{ vendors.length }} vendors</span></div><div class="vendor-grid"><a v-for="vendor in vendors" :key="vendor.id" class="vendor-card" :href="`index.html?view=vendor&id=${vendor.id}`"><div class="vendor-cover" :style="{ backgroundImage: `url(${vendor.cover_image || vendor.cover || 'https://images.unsplash.com/photo-1494526585095-c41746248156?w=800&q=60'})` }"><span class="vendor-badge">{{ vendor.category || 'Local' }}</span></div><div class="vendor-body"><div class="vendor-logo">{{ (vendor.logo_text || vendor.name || 'LC').slice(0, 2).toUpperCase() }}</div><h3>{{ vendor.name }}</h3><div class="vendor-category">{{ vendor.location || 'South Africa' }}</div><p class="vendor-desc">{{ vendor.description || 'Local vendor listing' }}</p><div class="vendor-meta"><span>★ {{ Number(vendor.rating || 0).toFixed(1) }}</span><span>Since {{ vendor.joined || 'Recently' }}</span></div></div></a></div></section></template>